SELECT album_id AS albumId, COUNT(*) AS photoCount FROM content_album_photo WHERE is_deleted = 0 AND album_id IN
#{albumId}
GROUP BY album_id

SELECT p.album_id, p.id, p.object_key, p.uploaded_by, p.created_at, p.updated_at, p.is_deleted FROM content_album a JOIN content_album_photo p ON p.album_id = a.id AND p.is_deleted = 0 WHERE a.is_deleted = 0 AND a.id IN
#{albumId}
AND p.id = COALESCE( (SELECT c.id FROM content_album_photo c WHERE c.id = a.cover_photo_id AND c.album_id = a.id AND c.is_deleted = 0), (SELECT MIN(m.id) FROM content_album_photo m WHERE m.album_id = a.id AND m.is_deleted = 0))
